# Frozen inference subset; generated by scripts/package_isa_forest.py.
"""Train-only phone vocabulary extending acoustic/timing/viseme channels."""
import numpy as np
from .phonetic_features import hybrid_features
PROFILE = 'acoustic-timing-phoneme-identity-v1'
GAP, UNKNOWN = ('<gap>', '<unknown>')

def identity_features(samples, rate, alignment, vocabulary):
    if not isinstance(vocabulary, list) or vocabulary[:2] != [GAP, UNKNOWN] or (not 3 <= len(vocabulary) <= 128) or (len(set(vocabulary)) != len(vocabulary)):
        raise ValueError('Invalid frozen phoneme vocabulary')
    base, times, hop = hybrid_features(samples, rate, alignment)
    phones = [p for p in alignment['phonemes'] if p['end'] > p['start']]
    starts = np.array([p['start'] for p in phones])
    ends = np.array([p['end'] for p in phones])
    indices = np.clip(np.searchsorted(starts, times, side='right') - 1, 0, len(phones) - 1)
    active = (times >= starts[indices]) & (times < ends[indices])
    lookup = {phone: i for i, phone in enumerate(vocabulary)}
    codes = np.array([lookup.get(phones[i]['phoneme'], 1) if present else 0 for i, present in zip(indices, active)])
    return (np.column_stack([base, np.eye(len(vocabulary))[codes]]), times, hop)
